import{_ as o,l as s,o as e,c as i,v as t,p as l,x as r,d as p,i as d,S as P}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"IP 编址与子网","description":"","frontmatter":{"title":"IP 编址与子网","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ip-subnet.md","filePath":"cs/ip-subnet.md","lastUpdated":1789023840000}'),c={name:"cs/ip-subnet.md"};function h(A,a,E,_,m,u){const n=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="ip-编址与子网" tabindex="-1">IP 编址与子网 <a class="header-anchor" href="#ip-编址与子网" aria-label="Permalink to &quot;IP 编址与子网&quot;">​</a></h1><div class="epigraph"><p>互联网数据报带上源与目的的全球地址；子网用掩码把地址切成「网络 + 主机」，同一网络内才直接 ARP。</p><footer>—— 据 Postel, RFC 791, Internet Protocol, 1981；Cerf and Kahn, 1974 整理</footer></div><p><a href="/cs/arp-cache">上一课</a>能在一跳上解析地址，但还没有说哪些 IP 算「一跳之内」。<a href="/cs/layering-e2e">分层</a>要主机到主机的网络层。缺口是 <strong>IPv4 编址与子网</strong>：32 位地址、掩码、同一子网直连，跨子网交给路由器。本课不把最长前缀匹配的查找结构写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若全球扁平 MAC 当唯一名字，路由表无法聚合，以太网也不能跨任意拓扑。Cerf 与 Kahn 把分组加上网络层地址，经异构网络转发。RFC 791：版本、头长度、TTL、协议号、源/目的地址。分类地址（A/B/C）浪费空间，子网与后来的 CIDR 用前缀长度 \\(n\\) 表示「前 \\(n\\) 位是网络」。缺口是这套编号，不是 BGP。</p><p>本课不把 NAT 提前；地址不够是更后的课。</p><p><span class="marginnote">主机：目的与自己同掩码则 ARP 目的；否则 ARP 默认网关。路由器：每接口一块子网。TTL 每跳减一，防环。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>接口配置地址与前缀。转发：若目的在直连前缀，解析该网 MAC；否则查路由表下一跳再 ARP 下一跳。分片：MTU 不够可切（后课 IPv6 对照会收紧）。校验和只盖 IP 头。载荷交给协议号指定的传输层——UDP/TCP 还没讲。</p>',9)),(e(),l(P,null,{default:r(()=>[d(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DST%5B%22%E7%9B%AE%E7%9A%84%20IP%22%5D%20--%3E%20MASK%5B%22%E4%B8%8E%E5%89%8D%E7%BC%80%E6%AF%94%E8%BE%83%22%5D%0A%20%20MASK%20--%3E%20LOCAL%5B%22%E5%90%8C%E7%BD%91%3A%20ARP%20%E7%9B%AE%E7%9A%84%22%5D%0A%20%20MASK%20--%3E%20GW%5B%22%E4%B8%8D%E5%90%8C%E7%BD%91%3A%20ARP%20%E7%BD%91%E5%85%B3%22%5D%0A%20%20GW%20--%3E%20RTR%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%E5%86%8D%E6%9F%A5%E8%A1%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>IP 让<a href="/cs/spanning-tree">生成树</a>只管一个广播域：不同子网可以、也应该分开广播域。端到端：IP 是尽力而为，丢包、乱序、重复都允许；可靠性留给传输层，符合 Saltzer 论证。进程仍看不见 IP 头，除非原始套接字；普通应用等到传输层。</p><p>与文件抽象的差别：IP 包是数据报，不是 inode 上的流。流是 TCP 的缺口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把移动 IP 与任意播当主干。不引入 IPv4 选项的源路由（安全问题留给安全课）。转发时如何在多条前缀里选最具体的一条，下一课最长前缀匹配。</p><p>广播地址与网络地址本身通常不分配给主机。CIDR 下「全零/全一」的旧分类禁忌部分放宽，配置仍要避开本网广播。</p><p>后课默认：主机用掩码决定直邻；跨网走路由器。路由表查找键是前缀，下一课 LPM。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IPv4 数据报按 32 位地址尽力转发（RFC 791）。</li><li>子网掩码划分直连范围；跨网 ARP 网关。</li><li>多前缀如何选中，是 LPM 的缺口。</li><li>出处：RFC 791；Cerf and Kahn, <em>IEEE Trans. Comm.</em> 1974；Kurose and Ross。</li></ul>',9))])}const C=o(c,[["render",h]]);export{f as __pageData,C as default};
